InterfaceAsPlainText.xhtml:
// Перечисление без значений и без базового типа
TYPE E_Color :
(
    Red,
    Green,
    Blue
);
END_TYPE

// Режим устройства: перечисление с явными значениями и базовым типом
{attribute 'qualified_only'}
{attribute 'strict'}
TYPE E_Mode :
(
    OutOfService := 0,  // выведено из работы
    Auto := 1,          // автоматический
    Manual := 2,        // ручной
    Local := 3          // местный
) INT;
END_TYPE

// Базовая структура: начальные значения, массив, строка, комментарии
TYPE ST_Base :
STRUCT
    xEnable : BOOL := TRUE;               // разрешение
    iCount : INT;                         (* счётчик *)
    rValue_bar : REAL := 1.5;
    sName : STRING(32) := 'base';
    wsLabel : WSTRING(16) := "Насос";
    aiData : ARRAY[0..3] OF INT := [1, 2, 3, 4];
    eMode : E_Mode := E_Mode.Auto;
END_STRUCT
END_TYPE

// Структура-наследник базовой
TYPE ST_Derived EXTENDS ST_Base :
STRUCT
    tDelay : TIME := T#5S;
    ltStamp : LTIME;
    pData : POINTER TO INT;
END_STRUCT
END_TYPE

// Псевдоним строкового типа
TYPE T_Name : STRING(20);
END_TYPE

// Псевдоним с поддиапазоном
TYPE T_Percent : INT(0..100);
END_TYPE

// Команды двигателя от HMI (DUT в папке проекта)
TYPE ST_MotorCmd :
STRUCT
    xStart : BOOL;
    xStop : BOOL;
    eMode : E_Mode := E_Mode.OutOfService;
END_STRUCT
END_TYPE

// Состояние двигателя для HMI (DUT во вложенной папке Motor/Status)
TYPE ST_MotorSts :
STRUCT
    xRun : BOOL;
    uiStarts : UINT;
    eMode : E_Mode := E_Mode.OutOfService;
END_STRUCT
END_TYPE

ST.xhtml:
// границы в правильном порядке
IF rMin <= rMax THEN
    rLow := rMin;
    rHigh := rMax;
ELSE
    rLow := rMax;
    rHigh := rMin;
END_IF
F_Clamp := LIMIT(rLow, rValue, rHigh);

InterfaceAsPlainText.xhtml:
// Назначение: ограничение значения диапазоном [rMin, rMax]; при rMin > rMax границы меняются местами
// Автор:      <ИМЯ ФАМИЛИЯ>
// Версия:     0.1.0
// Документ:   docs/plcopen.md
FUNCTION F_Clamp : REAL
VAR_INPUT
    rValue : REAL;      // значение
    rMin : REAL;        // нижняя граница
    rMax : REAL;        // верхняя граница
END_VAR
VAR
    rLow : REAL;
    rHigh : REAL;
END_VAR

// Назначение: функция без типа результата
// Автор:      <ИМЯ ФАМИЛИЯ>
// Версия:     0.1.0
// Документ:   docs/plcopen.md
FUNCTION F_Noop
VAR_INPUT
    xIn : BOOL;
END_VAR

ST.xhtml:
F_Sum := 0;
FOR diIdx := LOWER_BOUND(arValues, 1) TO UPPER_BOUND(arValues, 1) DO
    F_Sum := F_Sum + arValues[diIdx];
END_FOR

InterfaceAsPlainText.xhtml:
// Назначение: сумма элементов массива любой длины (VAR_IN_OUT CONSTANT, ARRAY[*])
// Автор:      <ИМЯ ФАМИЛИЯ>
// Версия:     0.1.0
// Документ:   docs/plcopen.md
FUNCTION F_Sum : LREAL
VAR_IN_OUT CONSTANT
    arValues : ARRAY[*] OF REAL;
END_VAR
VAR
    diIdx : DINT;
END_VAR

ST.xhtml:
fbEdge(CLK := xIn);
xEdge := fbEdge.Q;
IF xEdge THEN
    udiCount := udiCount + 1;
    udiTotal := udiTotal + 1;
END_IF
fbDelay(IN := xIn, PT := tConfirm, Q => xConfirmed);
stCmd.xStart S= xConfirmed;
stCmd.xStop R= xConfirmed;

InterfaceAsPlainText.xhtml:
// Назначение: счётчик фронтов с задержкой подтверждения (без ООП, Standard: R_TRIG, TON)
// Автор:      <ИМЯ ФАМИЛИЯ>
// Версия:     0.1.0
// Документ:   docs/plcopen.md
FUNCTION_BLOCK FB_Counter
VAR_INPUT
    xIn : BOOL;                 // вход
    tConfirm : TIME := T#100MS; // задержка подтверждения
END_VAR
VAR_OUTPUT
    udiCount : UDINT;           // число фронтов
    xConfirmed : BOOL;
END_VAR
VAR_IN_OUT
    stCmd : ST_MotorCmd;
END_VAR
VAR
    fbEdge : R_TRIG;
    fbDelay : TON;
END_VAR
VAR RETAIN
    udiTotal : UDINT;
END_VAR
VAR_TEMP
    xEdge : BOOL;
END_VAR

ST.xhtml:
(* внешний (* вложенный *) комментарий *)
itfPos := fbValve;
itfLock := fbValve;
itfPos.Setpoint := 50.0;
itfPos.MoveTo(rPos_pct := 40.0);
itfLock.Lock(xLock := NOT xDoRun);
fbValve();
Step(iInc := 1);
F_Noop(xIn := TRUE);
IF iCalls > 5 AND_THEN fbValve.rPos_pct < 1.0E3 THEN
    iCalls := 0;
END_IF

InterfaceAsPlainText.xhtml:
// Шаг программы
METHOD Step : INT
VAR_INPUT
    iInc : INT := 1;
END_VAR

// Назначение: программа с методом; комментарии всех видов
// Автор:      <ИМЯ ФАМИЛИЯ>
// Версия:     0.1.0
// Документ:   docs/plcopen.md
PROGRAM PRG_Aux
VAR
    fbValve : FB_Valve;
    itfPos : I_Positioner;
    itfLock : I_Lockable;
    iCalls : INT;
    wsMsg : WSTRING(32) := "Задвижка <закрыта> & 'ok'";
    sMsg : STRING(32) := 'a$'b"c <&>';
END_VAR
VAR_EXTERNAL
    xDoRun : BOOL;              // выход из GVL_Io (необязательное объявление CODESYS)
END_VAR

ST.xhtml:
(* вызовы всех объектов примера *)
itfDevice := fbMotor;
itfReset := fbMotor;
fbMotor(stCmd := stCmd);
IF itfDevice <> 0 THEN
    itfDevice.Mode := E_Mode.Auto;
    xOk := itfDevice.Fault;
END_IF
itfReset.Reset(xForce := TRUE);
fbCounter(xIn := GVL_Io.xDiStart, stCmd := GVL_Io.astCmd[GVL_Io.IO_CHANNELS - 1]);
GVL_Io.xDoRun := fbMotor.xRun;
stSts.xRun := fbMotor.xRun;
stSts.uiStarts := fbMotor.Starts;
rOut := F_Clamp(rValue := INT_TO_REAL(GVL_Io.iAiLevel), rMin := 0.0, rMax := 100.0);
lrSum := F_Sum(arValues := arBuf);
pValue := ADR(rOut);
refValue REF= rOut;
IF __ISVALIDREF(refValue) THEN
    refValue := refValue + GVL_Const.RATE_LIMIT;
END_IF
uRaw.wWord := 16#1234;
stDerived.tDelay := T#1S;
CASE iStep OF
    0:
        iStep := 1;
    1, 2:
        iStep := iStep + 1;
ELSE
    iStep := 0;
END_CASE
WHILE iStep > 10 DO
    iStep := iStep - 1;
END_WHILE
REPEAT
    iStep := iStep + 0;
UNTIL TRUE
END_REPEAT
GVL_Io.udiRunHours := GVL_Io.udiRunHours + fbCounter.udiCount;
PersistentVars.udiStartsTotal := PersistentVars.udiStartsTotal + fbMotor.Starts;
sName := GVL_Const.TEXT_OK;
eColor := E_Color.Blue;
ePercent := 75;
PRG_Aux();

InterfaceAsPlainText.xhtml:
// Назначение: точка входа — вызывает все объекты примера
// Автор:      <ИМЯ ФАМИЛИЯ>
// Версия:     0.1.0
// Документ:   docs/plcopen.md
PROGRAM PRG_Main
VAR
    fbMotor : FB_Motor;
    itfDevice : I_Device;
    itfReset : I_Resettable;
    fbCounter : FB_Counter;
    stCmd : ST_MotorCmd;
    stSts : ST_MotorSts;
    stDerived : ST_Derived;
    uRaw : U_Raw;
    ePercent : T_Percent := 50;
    sName : T_Name := 'pump';
    eColor : E_Color := E_Color.Green;
    arBuf : ARRAY[0..2] OF REAL := [3(1.0)];
    rOut : REAL;
    lrSum : LREAL;
    pValue : POINTER TO REAL;
    refValue : REFERENCE TO REAL;
    iStep : INT;
    xOk : BOOL;
END_VAR

ST.xhtml:
// общая логика базы: сброс по входу
IF xReset THEN
    Reset(xForce := FALSE);
END_IF
xFault := xFaultInt;

