// Сброс отказа
METHOD PUBLIC Reset : BOOL
VAR_INPUT
    xForce : BOOL;
END_VAR

// Установить отказ (только для наследников)
METHOD PROTECTED SetFault
VAR_INPUT
    xValue : BOOL;
END_VAR

// Назначение: абстрактная база устройств — режим, отказ, квитирование
// Автор:      <ИМЯ ФАМИЛИЯ>
// Версия:     0.1.0
// Документ:   docs/plcopen.md
{attribute 'reflection'}
FUNCTION_BLOCK ABSTRACT FB_DeviceBase IMPLEMENTS I_Device
VAR_INPUT
    xReset : BOOL;
END_VAR
VAR_OUTPUT
    xFault : BOOL;
END_VAR
VAR
    eModeInt : E_Mode := E_Mode.OutOfService;
    {attribute 'hide'}
    xFaultInt : BOOL;
END_VAR
VAR_STAT
    uiInstances : UINT;
END_VAR

ST.xhtml:
SUPER^();
IF stCmd.xStart AND NOT xFault THEN
    Start();
ELSIF stCmd.xStop THEN
    xRun := FALSE;
END_IF

