// Назначение: двигатель — наследник базы: пуск, сброс через SUPER^, счёт пусков
// Автор:      <ИМЯ ФАМИЛИЯ>
// Версия:     0.1.0
// Документ:   docs/plcopen.md
FUNCTION_BLOCK FB_Motor EXTENDS FB_DeviceBase
VAR_INPUT
    stCmd : ST_MotorCmd;
END_VAR
VAR_OUTPUT
    xRun : BOOL;
END_VAR
VAR
    uiStarts : UINT;
    fbCounter : FB_Counter;
END_VAR

ST.xhtml:
SUPER^();
IF NOT xLocked THEN
    rPos_pct := F_Clamp(rValue := rSetpoint_pct, rMin := 0.0, rMax := POS_MAX);
END_IF

rSetpoint_pct := rPos_pct;
xDone := THIS^.rPos_pct = rPos_pct;
MoveTo := NOT xLocked;

