// Объединение: одно слово как целое и как биты
TYPE U_Raw :
UNION
    wWord : WORD;
    aBytes : ARRAY[0..1] OF BYTE;
END_UNION
END_TYPE

// Константы
{attribute 'qualified_only'}
VAR_GLOBAL CONSTANT
    MAX_ITEMS : INT := 4;           // число элементов
    RATE_LIMIT : REAL := 0.25;
    TEXT_OK : STRING := 'OK';
END_VAR

// Входы-выходы и сохраняемые значения
VAR_GLOBAL
    xDiStart AT %IX0.0 : BOOL;      // кнопка «Пуск»
    xDoRun AT %QX0.0 : BOOL;
    iAiLevel AT %IW2 : INT;
    astCmd : ARRAY[1..GVL_Const.MAX_ITEMS] OF ST_MotorCmd;
END_VAR
VAR_GLOBAL RETAIN
    udiRunHours : UDINT;
END_VAR
VAR_GLOBAL CONSTANT
    IO_CHANNELS : INT := 2;         // число каналов (константа в одном списке с переменными)
END_VAR

// Сохраняемые переменные (объект Persistent Variables)
VAR_GLOBAL PERSISTENT RETAIN
    udiStartsTotal : UDINT;     // пуски за весь срок службы
    rRunHours_h : REAL;
END_VAR

// Переместить в позицию, %
METHOD MoveTo : BOOL
VAR_INPUT
    rPos_pct : REAL;
END_VAR
VAR_OUTPUT
    xDone : BOOL;
END_VAR

// Сбросить; TRUE — сброс выполнен
METHOD Reset : BOOL
VAR_INPUT
    xForce : BOOL;
END_VAR
